"""Application-owned dock/drawer and inert companion perch positioning."""
DOCK_CSS = r"""
__P__ body[data-vool-stage=chat]{--tb-drawer-width:clamp(248px,var(--tb-user-rail,300px),min(360px,calc(100vw - 72px)))}
__P__ #tb-dock{box-sizing:border-box;grid-area:rail;display:flex;flex-direction:column;align-items:center;gap:10px;padding:8px;width:56px;min-width:56px;height:100%;background:var(--panel);color:var(--ink);border-inline-end:1px solid var(--border);z-index:34}
__P__ #tb-dock button{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:40px;height:40px;min-width:40px;padding:8px;border:1px solid var(--border);border-radius:10px;background:var(--field);color:var(--ink);cursor:pointer}
__P__ #tb-dock button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
__P__ #tb-dock svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8;pointer-events:none}
__P__ #sidebar{display:flex!important;position:fixed!important;inset-inline-start:56px;inset-inline-end:auto;top:0;bottom:0;width:var(--tb-drawer-width)!important;min-width:0;z-index:33;box-shadow:4px 0 22px #0005;transform:translateX(calc(-100% - 56px));visibility:hidden;pointer-events:none}
__P__[dir=rtl] #sidebar{transform:translateX(calc(100% + 56px))}
__P__ body.sidebar-open #sidebar{transform:none;visibility:visible;pointer-events:auto}
__P__ #sideClose,__P__ #menu{display:inline-flex}
__P__ #sideResize{position:fixed;left:auto!important;right:auto!important;inset-inline-start:calc(56px + var(--tb-drawer-width));top:0;bottom:0;z-index:34;width:5px;visibility:hidden;pointer-events:none}
__P__ body.sidebar-open #sideResize{visibility:visible;pointer-events:auto}
__P__ #sideScrim{z-index:32}
__P__ body.sidebar-open #sideScrim{display:block}
@media(min-width:1000px){__P__ body[data-vool-stage=chat]{display:grid;grid-template-columns:56px 0 minmax(640px,1fr);grid-template-areas:'rail rail-grip stage'}__P__ body[data-vool-stage=chat].panel-open{grid-template-columns:56px 0 minmax(640px,1fr) 5px max-content;grid-template-areas:'rail rail-grip stage pane-grip pane'}}
@media(min-width:1000px) and (max-width:1199px){__P__ body[data-vool-stage=chat].panel-open{grid-template-columns:56px 0 minmax(640px,1fr);grid-template-areas:'rail rail-grip stage'}}
@media(max-width:999px){__P__ body[data-vool-stage=chat],__P__ body[data-vool-stage=chat].panel-open{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(0,1fr) 56px;grid-template-areas:'stage' 'rail';height:100dvh}__P__ #main{grid-area:stage;min-width:0;min-height:0;width:100%;height:100%;max-height:100%}__P__ #tb-dock{width:100%;min-width:0;height:56px;flex-direction:row;justify-content:center;border-inline-end:0;border-block-start:1px solid var(--border)}__P__ #sidebar{inset-inline-start:0;bottom:56px}__P__ #sideResize{inset-inline-start:var(--tb-drawer-width);bottom:56px}__P__ #sideScrim{bottom:56px}}
"""

CHROME_JS = r"""(()=>{'use strict';
const root=document.documentElement,protectedSelector="__TB_PROTECTED__",ids=['tbDockChats','tbDockNew','tbDockHome','tbDockSettings'];
let dock=null,sidebar=null,handle=null,dockEnabled=false,drawer=false,origin=null,sidebarAttrs=null,observer=null,resizeObserver=null,perch=null,perchEnabled=false,perchPending=0,perchTicket=0,perchEpoch=0,perchStamp='',petCanvas=null,drag=null,activityState='unknown',perchFoot=0,perchFootDirty=true;
const visible=e=>{if(!e?.isConnected)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&s.opacity!=='0'&&r.width>0&&r.height>0;};
const translated=(key,fallback)=>{const text=window.VOOLT?.(key);return text&&text!==key?text:fallback;};
function savedAttrs(node,names){return Object.fromEntries(names.map(k=>[k,node.getAttribute(k)]));}
function restoreAttrs(node,attrs){if(node&&attrs)for(const [key,value] of Object.entries(attrs))value===null?node.removeAttribute(key):node.setAttribute(key,value);}
function focusables(){return [...sidebar.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex]:not([tabindex="-1"])'),handle].filter(e=>visible(e)&&e.tabIndex>=0&&!e.closest('[inert]'));}
function closeDrawer(restore=true){if(!dockEnabled)return;document.body.classList.remove('sidebar-open');updateDrawer();if(restore&&origin?.isConnected)origin.focus();}
function updateDrawer(){if(!dockEnabled)return;const open=document.body.classList.contains('sidebar-open');dock.querySelector('#tbDockChats').setAttribute('aria-expanded',String(open));if(open===drawer)return;drawer=open;sidebar.inert=!open;handle.tabIndex=open?0:-1;if(open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');sidebar.setAttribute('aria-label',translated('sidebar.chats','Chats'));sidebar.setAttribute('aria-owns','sideResize');const first=focusables()[0];first?.focus();}else{restoreAttrs(sidebar,sidebarAttrs);sidebar.inert=true;if(sidebar.contains(document.activeElement)||document.activeElement===handle)origin?.focus();}}
function openDrawer(button,action){origin=button;if(!drawer){document.getElementById('menu').click();updateDrawer();}if(action)requestAnimationFrame(action);}
function addDockButton(id,key,fallback,path,action){const b=document.createElement('button');b.id=id;b.type='button';b.title=b.getAttribute('aria-label')||translated(key,fallback);b.setAttribute('aria-label',b.title);b.setAttribute('data-i18n-aria-label',key);b.setAttribute('data-i18n-title',key);const icon=document.createElement('template');icon.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path/></svg>';const svg=icon.content.firstElementChild;svg.firstElementChild.setAttribute('d',path);b.append(svg);b.onclick=()=>action(b);dock.append(b);return b;}
function syncDock(){const enabled=!!document.getElementById('sidebar')&&document.body.dataset.voolStage==='chat'&&root.dataset.voolLayout!=='standard'&&getComputedStyle(root).getPropertyValue('--tb-layout').trim()==='dock';if(enabled===dockEnabled){if(enabled)updateDrawer();return;}if(!enabled){closeDrawer(false);dockEnabled=false;dock?.remove();dock=null;restoreAttrs(sidebar,sidebarAttrs);if(sidebar)sidebar.inert=sidebarAttrs?.inert!==null;restoreAttrs(handle,handle?handle.__tbSaved:null);return;}sidebar=document.getElementById('sidebar');handle=document.getElementById('sideResize');sidebarAttrs=savedAttrs(sidebar,['role','aria-modal','aria-label','aria-owns','inert']);handle.__tbSaved=savedAttrs(handle,['role','aria-label','aria-orientation','tabindex']);document.body.classList.remove('sidebar-open');sidebar.inert=true;handle.tabIndex=-1;handle.setAttribute('role','separator');handle.setAttribute('aria-orientation','vertical');handle.setAttribute('aria-label',translated('chat.sidebar_resize',handle.title));dockEnabled=true;drawer=false;dock=document.createElement('nav');dock.id='tb-dock';dock.className='tb-root';dock.setAttribute('aria-label',translated('sidebar.chats','Chats'));document.body.insertBefore(dock,sidebar);
 const chats=addDockButton(ids[0],'header.menu_title','Toggle chats','M3 5h18M3 12h18M3 19h18',b=>drawer?closeDrawer():openDrawer(b));chats.setAttribute('aria-controls','sidebar');chats.setAttribute('aria-expanded','false');
 addDockButton(ids[1],'sidebar.new_chat','New chat','M12 3v18M3 12h18',b=>openDrawer(b,()=>document.getElementById('newChat').click()));
 addDockButton(ids[2],'sidebar.home','Home','M3 11l9-8 9 8M5 10v11h14V10M9 21v-8h6v8',b=>openDrawer(b,()=>{document.getElementById('homeMenu').open=true;document.getElementById('homeToggle').focus();}));
 addDockButton(ids[3],'sidebar.settings','Settings','M4 7h16M4 17h16M8 3v8M16 13v8',b=>openDrawer(b,()=>{document.getElementById('homeMenu').open=true;document.getElementById('settingsBtn').click();closeDrawer(false);}));}
function resizeDrawer(value,persist=false){const maximum=Math.max(248,Math.min(360,innerWidth-72)),width=Math.round(Math.max(248,Math.min(maximum,value)));root.style.setProperty('--tb-user-rail',width+'px');sidebar.style.width=width+'px';if(persist)try{localStorage.setItem('vool_sidebar_w',String(width));}catch(_){}queuePerch(true);}
document.addEventListener('mousedown',e=>{if(!dockEnabled||!drawer||e.target!==handle)return;e.preventDefault();e.stopImmediatePropagation();drag={x:e.clientX,width:sidebar.getBoundingClientRect().width,sign:root.dir==='rtl'?-1:1};},true);
window.addEventListener('mousemove',e=>{if(drag)resizeDrawer(drag.width+(e.clientX-drag.x)*drag.sign);});window.addEventListener('mouseup',()=>{if(drag){resizeDrawer(sidebar.getBoundingClientRect().width,true);drag=null;}});
document.addEventListener('click',e=>{if(dockEnabled&&drawer&&e.target.id==='sideScrim'){e.preventDefault();e.stopImmediatePropagation();closeDrawer();}},true);
document.addEventListener('focusin',e=>{if(dockEnabled&&drawer&&!sidebar.contains(e.target)&&e.target!==handle&&!dock.contains(e.target))closeDrawer(false);});
document.addEventListener('keydown',e=>{if(!dockEnabled||!drawer||e.defaultPrevented)return;if(e.key==='Escape'){if(e.target.classList?.contains('s-rename'))return;e.preventDefault();e.stopPropagation();closeDrawer();return;}if(e.target===handle&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const sign=root.dir==='rtl'?-1:1;resizeDrawer(e.key==='Home'?248:e.key==='End'?360:sidebar.getBoundingClientRect().width+(e.key==='ArrowRight'?16:-16)*sign,true);return;}if(e.key==='Tab'){const nodes=focusables(),first=nodes[0],last=nodes.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}},true);
function queuePerch(invalidate=false){if(invalidate){perchEpoch=(perchEpoch+1)%1073741824;perchFootDirty=true;}if(!perchEnabled||perchPending)return;const ticket=++perchTicket;perchPending=ticket;queueMicrotask(()=>{if(perchPending===ticket)updatePerch();});}
function updatePerch(){perchPending=0;if(!perchEnabled||!perch)return;const canvas=document.querySelector('#companionLayer > .vool-ninja > canvas');if(canvas!==petCanvas){resizeObserver?.disconnect();petCanvas=canvas;perchFootDirty=true;if(canvas&&typeof ResizeObserver==='function'){resizeObserver=new ResizeObserver(()=>queuePerch(true));resizeObserver.observe(canvas);}}if(!canvas||document.hidden||!visible(canvas)||!visible(canvas.parentElement)||!visible(canvas.parentElement.parentElement)){perch.hidden=true;perchStamp='';return;}const r=canvas.getBoundingClientRect();if(perchFootDirty){let foot=0;try{const pixels=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data;outer:for(let y=canvas.height-1;y>=0;y--)for(let x=Math.floor(canvas.width/4);x<Math.ceil(canvas.width*3/4);x++)if(pixels[(y*canvas.width+x)*4+3]>127){foot=y+1;break outer;}}catch(_){perch.hidden=true;return;}perchFoot=foot;perchFootDirty=false;}const foot=perchFoot;if(!foot){perch.hidden=true;perchStamp='';return;}const stamp=[r.x,r.y,r.width,r.height,foot,perchEpoch,root.dataset.voolActivity,canvas.parentElement.className].join(':');if(stamp===perchStamp)return;perchStamp=stamp;const width=Math.round(r.width*1.16),height=Math.round(width/5),left=Math.max(0,Math.min(innerWidth-width,Math.round(r.x+(r.width-width)/2))),top=Math.round(r.y+r.height*foot/canvas.height-height*5/32),box={left,right:left+width,top,bottom:top+height};let covered=left<0||left+width>innerWidth||top<0||top+height>innerHeight;
 if(!covered)for(const node of document.querySelectorAll(protectedSelector+',#tb-dock,#sidebar')){if(node===perch||node.closest('#companionLayer')||!visible(node))continue;const b=node.getBoundingClientRect();if(b.right>box.left&&b.left<box.right&&b.bottom>box.top&&b.top<box.bottom){covered=true;break;}}
 perch.hidden=covered;if(!covered)for(const [key,value] of Object.entries({left:left+'px',top:top+'px',width:width+'px',height:height+'px'}))if(perch.style[key]!==value)perch.style[key]=value;}
function protectedMutation(record){const t=record.target;if(record.type==='attributes'&&record.oldValue===t.getAttribute(record.attributeName))return false;if(t===perch||perch?.contains(t)||t===dock||dock?.contains(t))return false;if(t===document.body||t===petCanvas?.parentElement||t.id==='companionLayer')return true;if(t.nodeType===1&&(t.matches(protectedSelector)||t.closest(protectedSelector)))return true;return [...record.addedNodes,...record.removedNodes].some(n=>n.nodeType===1&&(n.matches(protectedSelector)||n.querySelector(protectedSelector)));}
function watch(){if(!dockEnabled&&!perchEnabled){observer?.disconnect();observer=null;return;}if(observer)return;observer=new MutationObserver(records=>{if(dockEnabled&&records.some(r=>r.target===document.body&&r.attributeName==='class'))updateDrawer();if(perchEnabled){const changes=records.filter(protectedMutation);if(changes.length)queuePerch(changes.some(r=>r.target!==petCanvas?.parentElement||r.attributeName!=='style'));}});observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeOldValue:true,attributeFilter:['class','style','hidden','aria-hidden']});}
function sync(){syncDock();const enabled=document.body.dataset.voolStage==='chat'&&getComputedStyle(root).getPropertyValue('--tb-has-perch').trim()==='1';if(enabled&&!perch){perch=document.createElement('div');perch.id='tb-perch';perch.setAttribute('aria-hidden','true');perch.hidden=true;perch.style.cssText='position:fixed;z-index:29;pointer-events:none;contain:layout paint;transition:none!important;animation:none!important';document.body.append(perch);}perchEnabled=enabled;if(!enabled){perchPending=0;perch?.remove();perch=null;resizeObserver?.disconnect();petCanvas=null;perchStamp='';}watch();queuePerch(true);}
window.addEventListener('vool-companion-painted',()=>{if(perchEnabled){perchFootDirty=true;queuePerch();}});
for(const event of ['vool-pet-media','vool-pets-changed'])window.addEventListener(event,()=>queuePerch(true));window.addEventListener('resize',()=>queuePerch(true));window.addEventListener('scroll',()=>queuePerch(true),true);document.addEventListener('visibilitychange',()=>{if(document.hidden&&perch)perch.hidden=true;queuePerch(true);});
window.VoolToyboxChrome={sync,activity(state){if(state!==activityState){activityState=state;queuePerch(true);}if(state==='approval'&&drawer)closeDrawer(false);},get diagnostics(){return {dock:dockEnabled,drawer,perch:!!perch&&!perch.hidden&&visible(perch)};}};
})();"""
